  .sc-app .callout[data-callout="sc-grade-c"] .callout[data-callout^="sc-c-"] a.internal-link { font-size: .8em; }
}
.is-mobile .sc-app .callout[data-callout="sc-colunas"] > .callout-content { grid-template-columns: minmax(0, 1fr); gap: 0; }

/* atalho "📂 Arquivos no Drive" no topo das páginas */
